begin;

-- ── посты ──
insert into public.posts (slug, title, subtitle, category_id, cover, blocks, read_min, published, sort_order) values (
  'google-jules', 'Агент, который работает без вас', 'Google Jules берёт одну задачу по вашему проекту и делает её, пока ноутбук закрыт', 'ai',
  '{"from":"#7C4DFF","to":"#150B2E","pattern":"rings"}'::jsonb, '[{"type":"text","text":"Jules — бесплатный агент от Google, который правит код в вашем проекте. Починить кнопку, добавить небольшую функцию, обновить библиотеку, написать тесты."},{"type":"text","text":"Отличие от обычного чата одно, зато важное: Jules работает не в браузере, а на своём сервере. Поставили задачу — можно закрыть ноутбук и вернуться, когда всё готово."},{"type":"callout","tone":"info","text":"Что нужно: аккаунт Google, аккаунт GitHub и проект, загруженный на GitHub. Ничего устанавливать не надо."},{"type":"heading","text":"1. Войдите"},{"type":"text","text":"Откройте jules.google.com и войдите через Google. При первом входе примите уведомление о конфиденциальности."},{"type":"heading","text":"2. Подключите GitHub"},{"type":"text","text":"Нажмите Connect to GitHub account. Дальше выберите репозиторий и ветку, с которой Jules будет работать."},{"type":"callout","tone":"warning","text":"GitHub предложит открыть доступ ко всем проектам сразу. Не соглашайтесь — отметьте только тот, который нужен."},{"type":"heading","text":"3. Опишите задачу"},{"type":"text","text":"Одна конкретная задача работает в разы лучше, чем «улучши проект». Вот шаблон для первого раза — в скобках подставьте своё."},{"type":"prompt","title":"Первая задача","text":"Разберись, почему [ЧТО НЕ РАБОТАЕТ].\n\nСначала составь план и пока ничего не меняй.\nПосле моего подтверждения исправь только эту проблему.\nНе трогай дизайн и остальные страницы.\nЗапусти проверки и покажи результат."},{"type":"text","text":"Нажмите Give me a plan."},{"type":"heading","text":"4. Прочитайте план"},{"type":"text","text":"Jules изучит проект и покажет, что собирается делать. Проверьте три вещи:"},{"type":"list","items":["правильно ли он понял проблему;","не лезет ли в лишние файлы;","написал ли, как проверит результат."]},{"type":"text","text":"Всё верно — подтверждайте. Что-то не так — напишите словами, что поправить, и Jules пересоберёт план."},{"type":"heading","text":"5. Закройте ноутбук"},{"type":"text","text":"Дальше Jules работает сам на сервере Google. Включите уведомления в Settings → Notifications — придёт письмо, когда задача будет готова или понадобится уточнение."},{"type":"heading","text":"6. Проверьте результат"},{"type":"text","text":"Откройте задачу и посмотрите, какие файлы изменились, прошли ли проверки и как Jules объяснил свою работу."},{"type":"callout","tone":"warning","text":"Не принимайте изменения вслепую. Что-то сделано не так — напишите замечание прямо в задаче, Jules переделает."},{"type":"heading","text":"7. Отправьте в проект"},{"type":"list","ordered":true,"items":["Нажмите Create branch.","Создайте Pull Request.","Ещё раз просмотрите изменения.","Только после этого сливайте в основную ветку."]},{"type":"heading","text":"Формула хорошей задачи"},{"type":"text","text":"Если задача не получается — почти всегда она описана слишком общо. Четыре строки спасают положение."},{"type":"code","lang":"text","code":"Контекст: что за проект и где проблема.\nЗадача: что конкретно сделать.\nОграничения: что нельзя трогать.\nПроверка: как убедиться, что работает."},{"type":"heading","text":"Что стоит поручать"},{"type":"list","items":["исправить конкретную ошибку;","добавить небольшую функцию;","подогнать один экран под телефон;","написать тесты;","обновить библиотеку."]},{"type":"text","text":"А вот «создай идеальное приложение» и «исправь всё» не сработают. Большую работу режьте на маленькие куски, которые можно проверить."},{"type":"heading","text":"Сколько это стоит"},{"type":"text","text":"Бесплатно — 15 задач в сутки и до 3 одновременно. Для начала более чем достаточно. Лимиты могут меняться, актуальные смотрите на jules.google/docs/usage-limits."},{"type":"heading","text":"Что в итоге"},{"type":"list","ordered":true,"items":["Войти через Google и подключить один репозиторий.","Описать одну конкретную задачу.","Прочитать план и подтвердить.","Закрыть ноутбук.","Проверить изменения и создать Pull Request."]},{"type":"callout","tone":"success","text":"Начать: jules.google.com. Документация: jules.google/docs."}]'::jsonb, 3, true, 0
) on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, category_id = excluded.category_id,
  cover = excluded.cover, blocks = excluded.blocks,
  read_min = excluded.read_min, sort_order = excluded.sort_order;

commit;
